-- =====================================================================
-- BANCO DE DADOS: GÊMEO DIGITAL DO PORTO DE SANTOS (POSTGRESQL / PGADMIN)
-- Gerado para o projeto /home/sergio/IdeaProjects/LineupBackend
-- =====================================================================

BEGIN;

-- 1. EXCLUSÃO LIMPA DE TABELAS EXISTENTES (SE HOUVER)
DROP TABLE IF EXISTS truck_schedules CASCADE;
DROP TABLE IF EXISTS highway_lines CASCADE;
DROP TABLE IF EXISTS highway_sectors CASCADE;
DROP TABLE IF EXISTS registered_trucks CASCADE;
DROP TABLE IF EXISTS highway_cargos CASCADE;
DROP TABLE IF EXISTS ship_schedules CASCADE;
DROP TABLE IF EXISTS berths CASCADE;
DROP TABLE IF EXISTS registered_vessels CASCADE;
DROP TABLE IF EXISTS port_cargo_catalog CASCADE;
DROP TABLE IF EXISTS tide_measurements CASCADE;
DROP TABLE IF EXISTS tide_tables CASCADE;
DROP TABLE IF EXISTS wagons CASCADE;
DROP TABLE IF EXISTS locomotives CASCADE;
DROP TABLE IF EXISTS wagon_allocations CASCADE;
DROP TABLE IF EXISTS locomotive_arrivals CASCADE;
DROP TABLE IF EXISTS train_compositions CASCADE;
DROP TABLE IF EXISTS rail_terminal_branches CASCADE;
DROP TABLE IF EXISTS rail_axis_yards CASCADE;

-- 2. CRIAÇÃO DAS TABELAS (DDL POSTGRESQL)

CREATE TABLE berths (
    id VARCHAR(64) PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    sector_name VARCHAR(255) NOT NULL,
    max_draft VARCHAR(32) NOT NULL,
    category VARCHAR(32) NOT NULL,
    display_order INTEGER NOT NULL
);

CREATE TABLE ship_schedules (
    id BIGSERIAL PRIMARY KEY,
    berth_id VARCHAR(64) NOT NULL REFERENCES berths(id) ON DELETE CASCADE,
    ship_name VARCHAR(255) NOT NULL,
    unloading_product VARCHAR(255) NOT NULL,
    loading_product VARCHAR(255) NOT NULL,
    tonnage INTEGER NOT NULL,
    start_day DOUBLE PRECISION NOT NULL,
    end_day DOUBLE PRECISION NOT NULL,
    stripe_color_hex VARCHAR(16) NOT NULL,
    status VARCHAR(40) NOT NULL
);

CREATE TABLE registered_vessels (
    imo_code VARCHAR(40) PRIMARY KEY,
    ship_name VARCHAR(255) NOT NULL,
    vessel_class VARCHAR(255) NOT NULL,
    max_draft_meters VARCHAR(32) NOT NULL,
    default_tonnage INTEGER NOT NULL,
    default_unload_product VARCHAR(255) NOT NULL,
    default_load_product VARCHAR(255) NOT NULL
);

CREATE TABLE port_cargo_catalog (
    product_code VARCHAR(40) PRIMARY KEY,
    product_name VARCHAR(255) NOT NULL,
    operation_direction VARCHAR(255) NOT NULL,
    cargo_profile VARCHAR(32) NOT NULL,
    average_rate_tons_day VARCHAR(64) NOT NULL
);

CREATE TABLE tide_tables (
    id BIGSERIAL PRIMARY KEY,
    month_key VARCHAR(255) NOT NULL UNIQUE,
    month_label VARCHAR(255) NOT NULL,
    source_file_name VARCHAR(255) NOT NULL,
    active_month BOOLEAN NOT NULL
);

CREATE TABLE tide_measurements (
    id BIGSERIAL PRIMARY KEY,
    tide_table_id BIGINT NOT NULL REFERENCES tide_tables(id) ON DELETE CASCADE,
    day_number INTEGER NOT NULL,
    time_str VARCHAR(10) NOT NULL,
    fractional_day DOUBLE PRECISION NOT NULL,
    height_meters DOUBLE PRECISION NOT NULL,
    high_tide BOOLEAN NOT NULL
);
CREATE INDEX idx_tide_meas_table_day ON tide_measurements(tide_table_id, day_number);

CREATE TABLE highway_sectors (
    sector_code VARCHAR(40) PRIMARY KEY,
    sector_name VARCHAR(255) NOT NULL,
    access_highway VARCHAR(255) NOT NULL,
    vehicle_profile VARCHAR(255) NOT NULL,
    gate_count INTEGER NOT NULL,
    color_hex VARCHAR(16) NOT NULL,
    operational_status VARCHAR(255) NOT NULL
);

CREATE TABLE highway_lines (
    line_number INTEGER PRIMARY KEY,
    line_code VARCHAR(255) NOT NULL UNIQUE,
    sector_name VARCHAR(255) NOT NULL,
    cargo_profile VARCHAR(255) NOT NULL,
    sector_color_hex VARCHAR(16) NOT NULL
);

CREATE TABLE truck_schedules (
    truck_id VARCHAR(40) PRIMARY KEY,
    line_number INTEGER NOT NULL REFERENCES highway_lines(line_number) ON DELETE CASCADE,
    plate_and_fleet VARCHAR(255) NOT NULL,
    carrier_name VARCHAR(255) NOT NULL,
    unloading_product VARCHAR(255) NOT NULL,
    loading_product VARCHAR(255) NOT NULL,
    tonnage DOUBLE PRECISION NOT NULL,
    start_slot INTEGER NOT NULL,
    end_slot INTEGER NOT NULL,
    color_hex VARCHAR(16) NOT NULL
);
CREATE INDEX idx_truck_sched_line ON truck_schedules(line_number, start_slot);

CREATE TABLE registered_trucks (
    truck_code VARCHAR(40) PRIMARY KEY,
    plate_and_fleet VARCHAR(255) NOT NULL,
    carrier_name VARCHAR(255) NOT NULL,
    truck_config_type VARCHAR(255) NOT NULL,
    max_capacity_tons DOUBLE PRECISION NOT NULL,
    default_unload_product VARCHAR(255) NOT NULL,
    default_load_product VARCHAR(255) NOT NULL
);

CREATE TABLE highway_cargos (
    cargo_code VARCHAR(40) PRIMARY KEY,
    product_name VARCHAR(255) NOT NULL,
    operation_direction VARCHAR(255) NOT NULL,
    equipment_type VARCHAR(255) NOT NULL,
    default_stay_duration VARCHAR(255) NOT NULL
);

CREATE TABLE locomotives (
    locomotive_code VARCHAR(80) PRIMARY KEY,
    model_power VARCHAR(255) NOT NULL,
    operator_axis VARCHAR(255) NOT NULL
);

CREATE TABLE wagons (
    wagon_code VARCHAR(64) PRIMARY KEY,
    product VARCHAR(255) NOT NULL,
    capacity VARCHAR(255) NOT NULL,
    origin_terminal VARCHAR(255) NOT NULL,
    destination_terminal VARCHAR(255) NOT NULL,
    locomotive_code VARCHAR(80) REFERENCES locomotives(locomotive_code) ON DELETE SET NULL
);

CREATE TABLE wagon_allocations (
    allocation_id VARCHAR(40) PRIMARY KEY,
    locomotive_code VARCHAR(255) NOT NULL,
    position_order VARCHAR(40) NOT NULL,
    wagon_code VARCHAR(64) NOT NULL,
    product VARCHAR(255) NOT NULL,
    capacity VARCHAR(255) NOT NULL,
    origin_terminal VARCHAR(255) NOT NULL,
    destination_terminal VARCHAR(255) NOT NULL
);

CREATE TABLE locomotive_arrivals (
    arrival_id VARCHAR(40) PRIMARY KEY,
    locomotive_code VARCHAR(255) NOT NULL,
    operator_axis VARCHAR(255) NOT NULL,
    date_formatted VARCHAR(20) NOT NULL,
    start_time VARCHAR(10) NOT NULL,
    end_time VARCHAR(10) NOT NULL,
    product VARCHAR(255) NOT NULL,
    wagon_summary VARCHAR(255) NOT NULL,
    origin_terminal VARCHAR(255) NOT NULL,
    destination_terminal VARCHAR(255) NOT NULL,
    status VARCHAR(255) NOT NULL
);

CREATE TABLE train_compositions (
    id BIGSERIAL PRIMARY KEY,
    prefix VARCHAR(64) NOT NULL,
    trunk_axis VARCHAR(32) NOT NULL,
    origin_state VARCHAR(255) NOT NULL,
    destination_terminal VARCHAR(255) NOT NULL,
    commodity VARCHAR(255) NOT NULL,
    wagon_count INTEGER NOT NULL,
    length_km DOUBLE PRECISION NOT NULL,
    tonnage INTEGER NOT NULL,
    scheduled_date DATE NOT NULL,
    arrival_hour INTEGER NOT NULL,
    duration_hours INTEGER NOT NULL,
    train_color_hex VARCHAR(16) NOT NULL
);

CREATE TABLE rail_terminal_branches (
    code VARCHAR(64) PRIMARY KEY,
    terminal_name VARCHAR(255) NOT NULL,
    region VARCHAR(255) NOT NULL,
    hopper_type VARCHAR(255) NOT NULL,
    main_commodity VARCHAR(255) NOT NULL,
    capacity_cars_per_day INTEGER NOT NULL,
    switch_active BOOLEAN NOT NULL,
    loop_angle_position DOUBLE PRECISION NOT NULL
);

CREATE TABLE rail_axis_yards (
    code VARCHAR(64) PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    category_type VARCHAR(255) NOT NULL,
    concessionaire VARCHAR(255) NOT NULL,
    max_train_length_km VARCHAR(255) NOT NULL,
    switch_amv_count INTEGER NOT NULL,
    operational_status VARCHAR(255) NOT NULL
);

